$ErrorActionPreference = 'Stop'

$ExpectedHead = 'ede5b0d30a6c103136c0da946fa9aa6522f0e889'
$Root = (& git rev-parse --show-toplevel 2>$null).Trim()
if (-not $Root) { throw 'No se pudo resolver la raiz Git.' }
Set-Location $Root

$Branch = (& git branch --show-current).Trim()
if ($Branch -ne 'main') { throw "Base invalida: se esperaba rama main y se encontro '$Branch'." }
$Head = (& git rev-parse HEAD).Trim()
if ($Head -ne $ExpectedHead) { throw "Base invalida: HEAD=$Head; esperado=$ExpectedHead." }

$Self = 'scripts/apply-fix-mvp-editorial-crud-desktop-001.ps1'
$dirty = @(& git status --short --untracked-files=all | Where-Object { $_ -and ($_ -notmatch [regex]::Escape($Self)) })
if ($dirty.Count -gt 0) {
  Write-Host ($dirty -join [Environment]::NewLine)
  throw 'El working tree debe estar limpio antes de aplicar el fix (salvo el propio instalador).'
}

function Decode([string]$Value) { [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value)) }

function Write-RepoFile([string]$Path, [string]$Base64) {
  $Full = Join-Path $Root $Path
  $Dir = Split-Path -Parent $Full
  if ($Dir) { New-Item -ItemType Directory -Force -Path $Dir | Out-Null }
  $Content = Decode $Base64
  if (Test-Path -LiteralPath $Full) {
    $Existing = [IO.File]::ReadAllText($Full, [Text.Encoding]::UTF8)
    if ($Existing -eq $Content) { Write-Host "OK: $Path ya estaba creado."; return }
    throw "El archivo nuevo $Path ya existe con contenido diferente."
  }
  [IO.File]::WriteAllText($Full, $Content, [Text.UTF8Encoding]::new($false))
  Write-Host "OK: creado $Path"
}

function Replace-Exact([string]$Path, [string]$Old64, [string]$New64, [int]$ExpectedCount = 1) {
  $Full = Join-Path $Root $Path
  if (-not (Test-Path -LiteralPath $Full)) { throw "No existe $Path." }
  $Text = [IO.File]::ReadAllText($Full, [Text.Encoding]::UTF8)
  $Old = Decode $Old64
  $New = Decode $New64
  if ($Text.Contains($New)) { Write-Host "OK: parche ya presente en $Path"; return }
  $Count = 0; $Pos = 0
  while (($Index = $Text.IndexOf($Old, $Pos, [StringComparison]::Ordinal)) -ge 0) { $Count++; $Pos = $Index + $Old.Length }
  if ($Count -ne $ExpectedCount) { throw "Bloque esperado en ${Path}: encontrados=$Count; esperado=$ExpectedCount." }
  $Updated = $Text.Replace($Old, $New)
  [IO.File]::WriteAllText($Full, $Updated, [Text.UTF8Encoding]::new($false))
  Write-Host "OK: parche aplicado en $Path"
}

